// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2021, "10-11", [{"author":"П. Аркадьев","question":"Какое слово сильно отличается от остальных по значению?","choices":["<em>носорог</em>","<em>осьминог</em>","<em>стремглав</em>","<em>утконос</em>","<em>трубкозуб</em>."],"key":"В","review":["Названия и способ движения","Носорог, осьминог, утконос и трубкозуб — названия животных. Их можно объединить по значению.","«Стремглав» значит очень быстро, стремительно. Это наречие о способе движения."]},{"author":"Е. Муравенко","question":"Какое выражение точно не термин?","choices":["<em>сложное слово</em>","<em>сложное предложение</em>","<em>простое предложение</em>","<em>простое число</em>","<em>простое упражнение</em>."],"key":"Д","review":["Выражение и термин","«Сложное слово», «сложное предложение» и «простое предложение» называют понятия грамматики. «Простое число» — математический термин.","«Простое упражнение» обычно означает лёгкое. Это свободная оценка, в которой «простое» не даёт специального определения."]},{"author":"И. Рубанов","question":"Какое слово по смыслу лишнее?","choices":["<em>миллиампер</em>","<em>милливольт</em>","<em>милликулон</em>","<em>миллиом</em>","<em>миллион</em>."],"key":"Д","review":["Общая часть «милли-»","В названиях «миллиампер», «милливольт», «милликулон» и «миллиом» часть «милли-» обозначает одну тысячную соответствующей единицы.","«Миллион» означает тысячу тысяч. Он является названием числа и не содержит приставку со значением тысячной доли."]},{"author":"Б. Иомдин","question":"Какое название жителя города образовано не так, как остальные?","choices":["<em>берлинец</em>","<em>пекинец</em>","<em>бакинец</em>","<em>лондонец</em>","<em>дублинец</em>."],"key":"В","review":["Жители городов","У Берлина, Пекина, Лондона и Дублина название заканчивается на Н. Перед суффиксом «-ец» сохраняется этот Н.","В названии Баку буквы Н нет. В слове «бакинец» появляется часть «-ин-», которой не было в названии города."]},{"author":"Б. Иомдин","question":"Что обычно делает не человек?","choices":["акает","ёкает","икает","окает","якает."],"key":"Б","review":["Что значит «ёкает»","Человек может «акать», «окать» или «якать», то есть произносить гласные определённым образом. «Икать» тоже может человек.","Говорят «сердце ёкает», когда человек внезапно пугается или волнуется. Подлежащее у этого глагола обычно «сердце»."]},{"author":"О. Подлесская","question":"Лера купила сапоги из замши. А как их назвать по-другому?","choices":["<em>замшивые</em>","<em>замшелые</em>","<em>замшевые</em>","<em>замшаные</em>","<em>замшеные</em>."],"key":"В","review":["Сапоги из замши","Материал называется «замша». Прилагательное описывает предмет, сшитый из этого материала.","Нормативное прилагательное «замшевый». Значит, сапоги замшевые."]},{"author":"О. Подлесская","question":"<em>Чем _____, лучше помириться.</em> В этой фразе мы пропустили глагол. Найдите в ответах однокоренное ему слово.","choices":["<em>воробей</em>","<em>ворона</em>","<em>индюк</em>","<em>петух</em>","<em>голубь</em>."],"key":"Г","review":["Вместо ссоры","В предложении подразумевается «Чем задираться, лучше помириться». Такой поступок может называться «петушиться».","Слово «петушиться» образовано от «петух». Оно рисует человека, который ведёт себя задиристо, как драчливая птица."]},{"author":"Б. Иомдин","question":"В каком примере слово <em>ба</em> означает совсем не то, что в остальных?","choices":["<em>Она ступила шага два и оторопела, увидя падчерицу. — Ба! — вскричала она, — а ты зачем здесь?</em> (В. Нарежный)","<em>Вынырнув на свет, девочка с этюдником через плечо, с листом картона под мышкой прикладывает ладошку козырьком к глазам и кричит задорно: — Ба! Поесть чё-т найдётся?!</em> (В. Ярмолинец)","<em>Минуту спустя Скудронжогло показался в дверях гостиной. — Ба, брат, ты здесь! — сказал он, увидев Платонова.</em> (Н. Гоголь)","<em>За дверью сада по ступеням лестницы слышны торопливые шаги. Кто это бежит так? Ба! Станицын!</em> (И. Тургенев)","<em>Она качалась, вытягивалась, словно пытаясь удержаться на дереве. Ба, да это же старая знакомая — древесная змея!</em> (С. Сахарнов)"],"key":"Б","review":["Междометие или обращение","В четырёх примерах «ба!» выражает удивление при неожиданной встрече или находке.","Девочка с этюдником окликает бабушку: «Ба! Поесть чё-т найдётся?!» Здесь «ба» — сокращённое обращение."]},{"author":"О. Подлесская","question":"Оля выписывала из словаря слова в две строчки:\n<em>Голосище, мужичище, сапожище, холодище, …\nЗаборище, морозище, пожарище, сугробище, …</em>\nКакое слово можно добавить в первую строчку?","choices":["<em>народище</em>","<em>болотище</em>","<em>позорище</em>","<em>заводище</em>","<em>кулачище</em>."],"key":"Д","review":["Ударение в двух рядах","Прочитай первый ряд с ударением на суффиксе: голоси́ще, мужичи́ще, сапожи́ще, холоди́ще. Во втором ударение остаётся раньше: забо́рище, моро́зище, пожа́рище, сугро́бище.","У «кулачи́ще» ударение как в первом ряду, на И в суффиксе."]},{"author":"Б. Иомдин","question":"Для этого знака использовались разные названия: <em>молчанка</em>, <em>черта</em>, <em>чёрточка</em>, <em>знак мыслеотделительный</em>. А как он называется сейчас?","choices":["<em>дефис</em>","<em>тире</em>","<em>дробь</em>","<em>минус</em>","<em>многоточие</em>."],"key":"Б","review":["Старые названия знака","Слово «молчанка» подсказывает паузу, а «мыслеотделительный» — разделение частей высказывания. «Черта» описывает форму.","Современный знак для такой паузы в предложении — тире."]},{"author":"О. Подлесская","question":"В четырёх анекдотах пропущены формы одного и того же слова, а в пятом ― другого. Найдите анекдот, в котором пропущено не то слово, что в остальных четырёх.","choices":["<em>______</em> — <em>это такое слово, которое пишут вместо того, правописание которого не знают.</em>","<em>Раньше я был просто бедным, но потом купил словарь ______ и стал нищим, неимущим, несостоятельным.</em>","<em>Хватит. Надоело. Достаточно. Больше не буду перед сном читать словарь ______.</em>","<em>Группа учёных занимается изучением научной проблемы. Проходит неделя, две, месяц… Наконец руководитель группы спрашивает: ― Господа, кто-нибудь знает ______ слова «эврика»?</em>","<em>Вы об этом никогда не задумывались, но антоним к слову «антоним» — ______.</em>"],"key":"Г","review":["Какого слова не хватает","Незнакомое написание заменяют синонимом. Словарь синонимов даёт к «бедному» другие слова. «Антоним» и «синоним» противопоставлены и в последней шутке.","В реплике про «эврику» учёным нужно значение слова. В остальных анекдотах пропущены формы слова «синоним», а здесь «значение»."]},{"author":"А. Анисимов","question":"Один пользователь иронично написал на форуме программистов: «Код, который называют „Х“, — символ трудолюбия. Ведь разработчик не ленится самостоятельно решать задачу, которая до него была решена гораздо лучше». А какое слово из сленга программистов мы заменили на X?","choices":["<em>автобус</em>","<em>бульдозер</em>","<em>велосипед</em>","<em>самосвал</em>","<em>троллейбус</em>."],"key":"В","review":["Метафора программистов","Программист в цитате заново делает то, что уже существует. Ищи известный оборот об изобретении чего-то давно известного.","«Изобретать велосипед» значит заново искать уже найденное решение. Поэтому такой код называют «велосипедом»."]},{"author":"Б. Иомдин","question":"Какой глагол чаще остальных встречается после тире?","choices":["<em>выстрелить</em>","<em>стрельнуть</em>","<em>выпалить</em>","<em>пальнуть</em>","<em>пульнуть</em>."],"key":"В","review":["Глагол после тире","После тире в диалоге часто стоит глагол, показывающий, как персонаж произнёс реплику: «сказал», «крикнул», «ответил».","«Выпалить» может значить «быстро и резко сказать». У остальных слов преобладает смысл выстрела."]},{"author":"П. Аркадьев","question":"Какое слово не может быть сравнительной степенью?","choices":["<em>вернее</em>","<em>позднее</em>","<em>раннее</em>","<em>свежее</em>","<em>синее</em>."],"key":"В","review":["Как сравнивают","У сравнительных форм можно добавить «намного»: намного вернее, позднее, свежее, синее.","«Раннее» бывает обычным прилагательным среднего рода: «раннее утро». Сравнивают иначе: «раньше» или «ранее»."]},{"author":"И. Шаронов","question":"В каком словосочетании притяжательное прилагательное образовано неправильно?","choices":["<em>пифагоровы штаны</em>","<em>авгиевы конюшни</em>","<em>ариаднова нить</em>","<em>бикфордов шнур</em>","<em>торричеллиева пустота</em>."],"key":"В","review":["Чья нить","Названия «пифагоровы штаны», «авгиевы конюшни», «бикфордов шнур» и «торричеллиева пустота» употребляются в этих формах.","От женского имени «Ариадна» образуется «Ариаднина». Устоявшееся выражение — «Ариаднина нить»."]},{"author":"П. Аркадьев","question":"По-французски — <em>Этьен</em>, по-венгерски — <em>Иштван</em>, по-испански — <em>Эстебан</em>, а по-русски — _____.","choices":["<em>Иван</em>","<em>Эдуард</em>","<em>Ефим</em>","<em>Тимофей</em>","<em>Степан</em>."],"key":"Д","review":["Имя в разных языках","Французское «Этьен», венгерское «Иштван» и испанское «Эстебан» восходят к одному имени, известному в форме «Стефан».","В русском это имя закрепилось в форме «Степан»."]},{"author":"Б. Иомдин","question":"<em>Тетрадь для работ по математике, физике и астрономии</em>. Какое существительное здесь не заимствовано из греческого языка?","choices":["<em>тетрадь</em>","<em>работа</em>","<em>математика</em>","<em>физика</em>","<em>астрономия</em>."],"key":"Б","review":["Греческие заимствования","«Тетрадь», «математика», «физика» и «астрономия» сохраняют греческие основы. Названия наук знают и в других европейских языках.","«Работа» — исконное славянское слово. Из пяти существительных оно не заимствовано из греческого."]},{"author":"Б. Иомдин","question":"Какой жанр так назвали потому, что когда-то это было повествование на языке, произошедшем от латыни?","choices":["повесть","роман","элегия","баллада","басня."],"key":"Б","review":["Название жанра","После распада Римской империи на основе латыни сложились романские языки. Название жанра сохранило это языковое обозначение.","Рассказ, написанный на романском языке вместо латыни, называли «романом». Позже слово стало обозначать литературный жанр."]},{"author":"Б. Иомдин","question":"Какое слово начинается не совсем так, как остальные?","choices":["<em>…вация</em>","<em>…земец</em>","<em>…сказание</em>","<em>…ходь</em>","все слова в (А)–(Г) начинаются одинаково."],"key":"А","review":["Где удваивается Н","Получаются «иноземец», «иносказание» и «иноходь». В этих словах первая часть пишется «ино-» с одной Н.","«Инновация» пишется с двумя Н. Это заимствование другого строения, хотя начало похожее."]},{"author":"С. Сай","question":"Какое из перечисленных слов может быть формой глагола?","choices":["<em>боль</em>","<em>горе</em>","<em>горесть</em>","<em>грусть</em>","<em>печаль</em>."],"key":"Д","review":["Существительное и глагол","Проверь, какое слово можно употребить как просьбу или приказ. Например, «не огорчай» можно заменить старым «не печаль».","«Печаль» бывает существительным, но в таком употреблении это повелительная форма глагола «печалить»."]},{"author":"И. Скоморохова","question":"Мальчик пришёл на детскую площадку и знакомится с ребятами: «Привет, меня зовут Александр, мне через год будет семь лет». Какой звук он не выговаривает?","choices":["[р]","[л]","[ф]","[ш]","[щ]."],"key":"Г","review":["Как сказано о возрасте","Ребёнку сейчас шесть лет, раз через год будет семь. Вместо короткой фразы он выбрал более длинную.","В слове «шесть» есть [ш]. И в коротком имени «Саша» есть этот звук. Мальчик избегает произносить [ш] в обоих случаях."]},{"author":"Б. Иомдин","question":"В каком примере даны антонимы?","choices":["<em>завиральный — противовирусный</em>","<em>пожарный — противопожарный</em>","<em>действие — противодействие</em>","<em>ток — противоток</em>","<em>показание — противопоказание</em>."],"key":"Д","review":["Противоположные рекомендации","«Противопожарный» значит направленный на предотвращение пожара, «противоток» описывает другое направление тока. Части «противо-» недостаточно для антонимии.","«Показание» в медицине — основание назначить лечение. «Противопоказание» означает причину его не применять. Эти значения противоположны."]},{"author":"И. Рубанов","question":"Что может, как правило, сделать только живое существо?","choices":["отстояться","отсидеться","отлежаться","отвисеться","среди четырёх предыдущих ответов нет правильного."],"key":"Б","review":["Кто может так поступить","Жидкость может отстояться, тесто — отлежаться, одежда — отвисеться. Во всех трёх случаях живое существо для действия не нужно.","«Отсидеться» значит провести время в укрытии или дождаться окончания опасности. Это обычно делает живое существо."]},{"author":"Е. Муравенко","question":"Даны предложения из художественной литературы. В каком из них в выделенном слове содержится ошибка?","choices":["<em>Долгую минуту стоял абсолютно неподвижно, <strong>вспоминая</strong>, всё ли взято.</em> (Анатолий Азольский)","<em>Не проходит дня, чтобы я тебя не <strong>вспомянул</strong>.</em> (Виктор Астафьев)","<em><strong>Помятуя</strong> о просьбе военрука, Витька обогнул школу и через открытый вход в тир беспрепятственно проник внутрь</em>. (Алексей Иванов)","<em>Витька, не к ночи будь <strong>помянут,</strong> научил собирать улики и подтверждать алиби.</em> (Ольга Новикова)","<em>Было также многозначительно <strong>упомянуто</strong> о его проекте, уже несколько лет лежавшем под сукном…</em> (Людмила Улицкая)"],"key":"В","review":["Пропущенная точность","«Вспоминая», «вспомянул», «помянут» и «упомянуто» — существующие формы глаголов, связанных с памятью.","Литературное деепричастие — «памятуя», от «память». В третьем примере написали «помятуя»."]},{"author":"Б. Иомдин","question":"Какое слово никогда не имело общего корня с остальными?","choices":["<em>вселенная</em>","<em>всемерный</em>","<em>всероссийский</em>","<em>завсегдатай</em>","<em>повседневный</em>."],"key":"А","review":["Две похожие части слова","«Всемерный», «всероссийский», «завсегдатай» и «повседневный» связаны с формами слова «весь», со значением полноты или повторяемости.","«Вселенная» происходит от «вселить» и первоначально означало населённый мир. Его корень «-сел-» связан с расселением."]},{"author":"И. Шаронов","question":"Сколько в списке правильных устойчивых выражений: <em>Тришкин халат</em>, <em>с гулькин хвост</em>, <em>Валтасаров дар</em>, <em>Прокрустова ложа</em>, <em>Сизифовы муки</em>?","choices":["ни одного","одно","два","три","четыре."],"key":"А","review":["Искажённые выражения","Сверь известные обороты: «Тришкин кафтан», «с гулькин нос», «Валтасаров пир». Первые три варианта искажают существительные.","Говорят также «Прокрустово ложе», «Сизифов труд» и «Танталовы муки». В списке нет ни одного правильно записанного оборота."]},{"author":"Е. Муравенко","question":"Слова <em>дре́во</em> и <em>ведро́</em> — анаграммы, т. е. состоят из одних и тех же букв. А сколько в них одинаковых звуков?","choices":["один","два","три","четыре","пять."],"key":"А","review":["Буквы и звуки","В «дре́во» мягкий [р’] и твёрдый [в], а в «ведро́» твёрдый [р] и мягкий [в’]. Одинаковые буквы передают разные согласные.","Гласные тоже различаются из-за ударения и соседних звуков. Совпадает только твёрдый [д]."]},{"author":"С. Переверзева","question":"Готовясь к экзамену по русскому языку, отличница Машенька записывала со слуха отрывок из радиопостановки одной пьесы XIX века. Позже, проверяя себя, она обнаружила, что одна реплика у неё записана иначе, чем в тексте пьесы, хотя смысл при этом остался практически тем же самым. Что написала Машенька?","choices":["— <em>Слушаюсь</em>","— <em>Извольте</em>","— <em>Прощайте</em>","— <em>Довольно</em>","— <em>Клянусь</em>."],"key":"А","review":["Запись с голоса","В пьесах XIX века к вежливой реплике могли прибавлять «-с». Эта частица возникла как сокращение обращения «сударь».","«Слушаю-с» можно было услышать и записать как «Слушаюсь». Смысл согласия выполнять распоряжение при этом почти сохраняется."]},{"author":"Е. Муравенко","question":"Глаголы <em>сравнивать</em>, <em>закапывать</em>, <em>засыпáть</em> обладают довольно редким свойством. Какой из глаголов также обладает этим свойством?","choices":["<em>застывать</em>","<em>отрывать</em>","<em>рассаживать</em>","<em>достраивать</em>","<em>вырезáть</em>."],"key":"Б","review":["Неоднозначность глагола","«Сравнивать» можно величины или что-нибудь с землёй, «закапывать» — яму или лекарство, «засыпать» — грунтом или от усталости. В каждом случае одно написание покрывает два действия.","«Отрывать» можно обрывок от бумаги или, от глагола «рыть», углубление в земле. У двух несовершенных глаголов получается одна форма."]},{"author":"Л. Фёдорова","question":"Кристина выписывала фрагменты фраз из одного текста:\n1) <em>Действие Четырнадцатой песни разворачивается в двух небесах:</em>\n2) <em>в Небе Солнца (завершая беседы с мудрецами, которые начались ещё в Десятой песни)</em>\n3) <em>и в Небе Марса (начиная важнейшую автобиографическую тему поэмы, которая продлится до середины Восемнадцатой песни…).</em>\n4) <em>Он избран для этой роли, вероятно, потому что почитался автором «Песни Песней».</em>\nВ каком примере Кристина сделала орфографическую ошибку?","choices":["в первом","во втором","в третьем","в четвёртом","ошибки нет, Кристина всё выписала правильно."],"key":"Д","review":["Формы слова «песнь»","Есть существительные «песня» и «песнь». В предложном падеже «в песне» относится к первому, а «в песни» — ко второму.","В родительном падеже «песни» возможно у обоих. Название «Песнь Песней» после слова «автором» тоже принимает форму «Песни Песней». Ошибки ни в одном фрагменте нет."]}], {"year":2021,"grade":"10-11","tasksFile":"10-11.pdf","answersFile":"10-11-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2021-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
